CREATE TABLE ezcontentobject_version (id INT AUTO_INCREMENT NOT NULL, contentobject_id INT DEFAULT NULL, created INT DEFAULT 0 NOT NULL, creator_id INT DEFAULT 0 NOT NULL, initial_language_id BIGINT DEFAULT 0 NOT NULL, language_mask BIGINT DEFAULT 0 NOT NULL, modified INT DEFAULT 0 NOT NULL, status INT DEFAULT 0 NOT NULL, user_id INT DEFAULT 0 NOT NULL, version INT DEFAULT 0 NOT NULL, workflow_event_pos INT DEFAULT 0, INDEX ezcobj_version_status (status), INDEX idx_object_version_objver (contentobject_id, version), INDEX ezcontobj_version_obj_status (contentobject_id, status), INDEX ezcobj_version_creator_id (creator_id), PRIMARY KEY(id)) DEFAULT CHARACTER SET utf8 COLLATE `utf8_unicode_ci` ENGINE = InnoDB;
